import { useState } from 'react';
import {
  Card,
  Stack,
  TextField,
  HelperText,
  Select,
  SelectOption,
  Switch,
  Button,
  Alert,
  Heading,
} from '@jinx-ui/react';

type Role = 'member' | 'admin' | 'viewer';

const ROLE_OPTIONS: { value: Role; label: string }[] = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('member');
  const [notify, setNotify] = useState(true);
  const [touched, setTouched] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email.trim());
  const showEmailError = touched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTouched(true);
    if (!canSubmit) return;
    setSubmitted(true);
  };

  const handleReset = () => {
    setEmail('');
    setRole('member');
    setNotify(true);
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="md" style={{ maxWidth: 420 }}>
      {submitted && (
        <Alert
          variant="success"
          onClose={() => {
            setSubmitted(false);
            handleReset();
          }}
        >
          Приглашение отправлено на {email.trim()}.
        </Alert>
      )}

      <Card padding="lg">
        <form onSubmit={handleSubmit} noValidate>
          <Stack direction="column" gap="md">
            <Heading level={3}>Пригласить в команду</Heading>

            <Stack direction="column" gap="xs">
              <TextField
                label="Email"
                type="email"
                value={email}
                placeholder="name@company.com"
                invalid={showEmailError}
                onChange={(e) => setEmail(e.target.value)}
                onBlur={() => setTouched(true)}
              />
              <HelperText tone={showEmailError ? 'danger' : 'neutral'}>
                {showEmailError
                  ? 'Похоже, это не похоже на email-адрес.'
                  : 'На эту почту придёт приглашение присоединиться к команде.'}
              </HelperText>
            </Stack>

            <Select
              label="Роль"
              value={role}
              onChange={(value) => setRole(value as Role)}
            >
              {ROLE_OPTIONS.map((option) => (
                <SelectOption key={option.value} value={option.value}>
                  {option.label}
                </SelectOption>
              ))}
            </Select>

            <Switch
              checked={notify}
              onChange={(checked) => setNotify(checked)}
              label="Отправить уведомление на почту"
            />

            <Button type="submit" variant="primary" disabled={!canSubmit}>
              Отправить приглашение
            </Button>
          </Stack>
        </form>
      </Card>
    </Stack>
  );
}

